import re


class ASTNode:
    def __init__(self, type, children=None):
        self.type = type
        self.children = children or []


def tokenize(text):
    return re.findall(r'\S+', text)


def parse(input_str):
    tokens = tokenize(input_str)
    if not tokens:
        return ASTNode(type="empty")
    return build_ast(tokens)


def build_ast(tokens):
    root = ASTNode(type="document")
    for tok in tokens:
        root.children.append(ASTNode(type="token", value=tok))
    return root

